    let (shutdown_tx_0, engine_task_0) = spawn_mock_utility_engine(
        handshake_address.clone(),
        b"engine-0".to_vec(),
        "is_sleeping",
        Value::Array(vec![]),
        true,
    );
    let (shutdown_tx_1, engine_task_1) = spawn_mock_utility_engine(
        handshake_address.clone(),
        b"engine-1".to_vec(),
        "is_sleeping",
        Value::Array(vec![]),
        false,
