            bootstrap_port: None,
        },
    ]);
    let app = build_router(ctx);

    let res = app.oneshot(chat_request()).await.unwrap();
    assert_eq!(res.status(), StatusCode::OK);
    let decode_urls: HashSet<String> = [decode_a.url.clone(), decode_b.url.clone()]
        .into_iter()
        .collect();
    let hdr = res
        .headers()
